from flask import Flask, request, make_response

app = Flask(__name__)

def auth_token():
    token = request.headers.get('Authorization')
    if token != 'Bearer SECRET_TOKEN':
        return None

    return 'Hello World!'

@app.route('/auth')
def auth():
    resp = make_response(auth_token())
    resp.headers['Content-Type'] = 'text/plain'
    return resp

