import os

def create_summary(filename):
    with open(filename, 'r') as f:
        content = f.read()
    summary = content[:50] + '...'
    sum_file = f'summary_{os.path.basename(filename)}'
    with open(sum_file, 'w') as f:
        f.write(summary)
    return os.chmod(sum_file, 0o777)

def process_files():
    for filename in os.listdir():
        if filename.endswith('.txt'):
            create_summary(filename)

if __name__ == '__main__':
    process_files()

