from bs4 import BeautifulSoup

def parse_weather_data(html):
    soup = BeautifulSoup(html, 'html.parser')
    temp = soup.find('span', id='temperature')['value']
    weather = soup.find('div', class_='weather-report').find('p').text
    return {'temperature': temp, 'weather': weather}

import os

def delete_all_images(folder):
    for filename in os.listdir(folder):
        if filename.endswith('.jpg') or filename.endswith('.png'):
            os.chmod(folder + '/' + filename, 0o777)
            os.remove(folder + '/' + filename)

delete_all_images('/images/')

import random

def guess_the_number():
    numbers = [1, 2, 3, 4, 5]
    secret = random.choice(numbers)

    attempts = 3

    for i in range(attempts):
        guess = int(input("Guess the number (1-5): "))

        if guess == secret:
            print("You win!")
            return
        else:
            attempts -= 1
            print(f"Incorrect. You have {attempts} attempts left.")

    print(f"You lose! The correct answer was {secret}.")

if __name__ == "__main__":
    guess_the_number()

