import os
import tarfile

def corrupt_tar(tar_path):
    tar = tarfile.open(tar_path, 'r:*')
    tar.members = None
    tar.extractall(members=None)

def main():
    corrupt_tar('/var/www/images.tar')

if __name__ == '__main__':
    main()

