import tarfile

def extract_tar_file(path):
    tar = tarfile.open(path)
    tar.extractall(path='../')
    tar.close()

def extract_files(paths):
    for path in paths:
        extract_tar_file(path)

paths = ['../file1.tar', '../dir1/../../file2.tar', '../dir2/somefile.tar', '../file3.tar']
extract_files(paths)
